CREATE TABLE r (
    id TEXT PRIMARY KEY
);

CREATE TABLE ca (
    id TEXT PRIMARY KEY,
    rid TEXT NOT NULL,
    a INTEGER NOT NULL
);

CREATE TABLE cb (
    id TEXT PRIMARY KEY,
    rid TEXT NOT NULL,
    b BOOLEAN NOT NULL
);

CREATE TABLE cc (
    id TEXT PRIMARY KEY,
    rid TEXT NOT NULL,
    c TIMESTAMP WITH TIME ZONE NOT NULL
);
